# area: callables
# hypothesis: Callable parameters are contravariant, so a function typed Callable[[Callable[[float], None]], None] is not assignable where Callable[[Callable[[int], None]], None] is expected; the call pass_consumer(h, ...) must be rejected, and at runtime h passes the float 1.5 to the int-only consumer, which fails with AttributeError.
from collections.abc import Callable
from typing import reveal_type


def make_consumer() -> Callable[[int], None]:
    return lambda v: print(v.bit_length())


def h(cb: Callable[[float], None]) -> None:
    cb(1.5)


def pass_consumer[T](f: Callable[[Callable[[T], None]], None], cons: Callable[[T], None]) -> None:
    f(cons)


def probe() -> str:
    try:
        pass_consumer(h, make_consumer())  # expect-error: T would need to be float and int at once
    except AttributeError:
        return 'AttributeError'
    return 'ok'


reveal_type(make_consumer())
print(probe())
